    WHERE NOT EXISTS (SELECT 1 FROM dbo.posts WITH (UPDLOCK, HOLDLOCK) WHERE id = s.id);
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
