import unittest

def parse_likes(raw):
    value = int(raw)
    if value < 0:
        raise ValueError("点赞数不能为负")
    return value

class LikesTests(unittest.TestCase):
    def test_zero_and_positive(self):
        self.assertEqual(parse_likes("0"), 0)
        self.assertEqual(parse_likes("12"), 12)

    def test_dirty_and_negative(self):
        for value in ("未知", "-1"):
            with self.subTest(value=value):
